# order_service.py
def create_order(user_id, cart_id, total):
    cart = CartRepository.get(cart_id)
    if cart.user_id != user_id:
        raise PermissionError('Cart does not belong to user')
    return OrderRepository.create(
        user_id=user_id,
        cart_id=cart_id,
        total=total,
        status='confirmed',
    )

