@app.route('/apply-coupon', methods=['POST'])
@login_required
def apply_coupon():
    cart_id = request.json['cart_id']
    coupon_code = request.json['coupon_code']
    cart = CartService.get_cart(cart_id, current_user.id)
    coupon = CouponService.validate(coupon_code, cart)  # checks min_order_amount
    if not coupon:
        return jsonify({'error': 'Invalid coupon'}), 400
    CartService.apply_coupon(cart_id, coupon.id)
    return jsonify({'discount': coupon.discount_pct})

@app.route('/checkout', methods=['POST'])
@login_required
def checkout():
    cart_id = request.json['cart_id']
    cart = CartService.get_cart(cart_id, current_user.id)
    # Apply discount if coupon was previously set
    if cart.coupon_id:
        coupon = CouponService.get(cart.coupon_id)
        discount = cart.subtotal * coupon.discount_pct / 100
    else:
        discount = 0
    total = cart.subtotal - discount
    order = OrderService.create(cart, total)
    PaymentService.charge(order.id, total)
    return jsonify({'order_id': order.id, 'total': total})

