@app.route('/register/step1', methods=['POST'])
def step1_personal_info():
    data = request.json
    user = UserService.create_pending(data['email'], data['name'])
    session['pending_user_id'] = user.id
    session['step'] = 1
    return jsonify({'next': '/register/step2'})

@app.route('/register/step2', methods=['POST'])
def step2_email_verify():
    # Requires user to click email verification link
    token = request.json.get('token')
    user_id = session.get('pending_user_id')
    if not user_id:
        return jsonify({'error': 'No pending registration'}), 400
    UserService.verify_email(user_id, token)
    session['step'] = 2
    return jsonify({'next': '/register/step3'})

@app.route('/register/step3', methods=['POST'])
def step3_complete():
    user_id = session.get('pending_user_id')
    if not user_id:
        return jsonify({'error': 'No pending registration'}), 400
    # Completes registration regardless of which step user came from
    UserService.activate(user_id)
    session.clear()
    return jsonify({'status': 'registered'})

# UserService.activate() does not check email_verified flag

