@app.route('/orders/<order_id>/refund', methods=['POST'])
@login_required
def request_refund(order_id):
    order = OrderRepository.get(order_id, current_user.id)
    if order.status != 'completed':
        return jsonify({'error': 'Order not eligible for refund'}), 400
    # Process refund
    refund = RefundService.process(order)
    return jsonify({'refund_id': refund.id, 'amount': refund.amount})

# refund_service.py
class RefundService:
    def process(self, order):
        if order.status != 'completed':
            raise ValueError('Cannot refund non-completed order')
        # Call payment provider
        payment_result = PaymentProvider.refund(
            transaction_id=order.payment_transaction_id,
            amount=order.total,
        )
        # Update order status after payment provider call
        OrderRepository.update_status(order.id, 'refunded')
        return RefundRepository.create(
            order_id=order.id,
            amount=order.total,
            provider_ref=payment_result['refund_id'],
        )

# Race condition: two concurrent POST /orders/123/refund
# Both pass status check ('completed') before either updates status to 'refunded'

