class TransferService:
    APPROVAL_THRESHOLD = Decimal('10000')

    def create(self, from_user, to_account, amount):
        status = 'pending_approval' if amount >= self.APPROVAL_THRESHOLD else 'auto_approved'
        return TransferRepository.create(
            from_user_id=from_user.id,
            to_account=to_account,
            amount=amount,
            status=status,
        )

    def approve(self, transfer, approver):
        # Missing: check approver != transfer requester
        # Missing: check approver has approval role
        transfer.status = 'approved'
        LedgerService.execute(transfer)
        TransferRepository.save(transfer)

