@app.route('/refunds/<order_id>/approve', methods=['POST'])
@login_required
def approve_refund(order_id):
    approver = current_user
    refund = refund_repo.get_pending(order_id)
    if refund is None:
        abort(404)
    if approver.id == refund.requested_by:
        abort(403)
    refund_service.approve(refund, approver)
    return jsonify(status='approved')

# refund_service.py
class RefundService:
    def approve(self, refund, approver):
        refund.status = 'APPROVED'
        refund.approved_by = approver.id
        self.ledger.post_refund(refund.order_id, refund.amount)
        self.repo.save(refund)

# checkout_service.py
def apply_discounts(cart, user):
    subtotal = cart.subtotal()
    total = subtotal
    points_value = user.loyalty_points * 0.01
    total -= points_value
    promo = cart.promo_code
    if promo and promo.valid():
        total -= subtotal * promo.percent_off
    return max(total, 0)

# promo_engine.py
class PromoCode:
    def __init__(self, code, percent_off, tier):
        self.code = code
        self.percent_off = percent_off
        self.tier = tier
    def valid(self):
        return self.percent_off > 0

