@app.route('/wires', methods=['POST'])
@login_required
def create_wire():
    payee_id = request.json['payee_id']
    amount = Decimal(request.json['amount'])
    payee = payee_repo.get(current_user.id, payee_id)
    if payee is None:
        abort(404)
    if amount > current_user.daily_limit_remaining():
        abort(402)
    wire = wire_service.release(current_user, payee, amount)
    return jsonify(id=wire.id, status=wire.status)

# wire_service.py
class WireService:
    def release(self, user, payee, amount):
        txn = self.repo.create(user.id, payee.id, amount, status='RELEASED')
        self.rails.submit(txn)
        return txn
